entries[301411] = { ["name"] = "Bequemes Reitgeschirr", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nRauer Lederharnisch (2), Meeresbrisensatteldecke (2)\nStellt ein bequemes Reitgeschirr her.\nBeruf:\nLederverarbeitung von Battle for Azeroth (150)\nLehrer:\nJada\nZone:\nNazjatar\nKosten:\n65\n\nBequemes Reitgeschirr\nBenutzen: Im Reittierausrüstungsplatz anlegen, um während des Reitens nicht benommen gemacht werden zu können. Funktioniert nicht auf Schlachtfeldern oder in Arenen.\n10" }
entries[301412] = { ["name"] = "Leichtlaufhufplatten", ["text"] = "Wirken in 3.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nUmbralsplitter (2), Düsterstaub (30), Monelitgehärtete Hufplatten\nStellt einen verzauberten Satz Leichtlaufhufplatten her.\nBerufsausbilder:\nVerzauberkunst von Battle for Azeroth (155)\nKosten:\n92\n50\n\nLeichtlaufhufplatten\n(0)\nBenutzen: Im Reittierausrüstungsplatz anlegen, um die Geschwindigkeit Eures Reittiers am Boden um 20% zu erhöhen. Funktioniert nicht auf Schlachtfeldern oder in Arenen und ist nicht mit anderen Effekten zur Erhöhung der Reitgeschwindigkeit stapelbar.\n10" }
entries[301413] = { ["name"] = "Aufblasbare Reittierschuhe", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nMonelitgehärtete Hufplatten , Sedimentlederblase (8)\nStellt einen Satz aufblasbare Reittierschuhe her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (150)\nLehrer:\nJada\nZone:\nNazjatar\nKosten:\n65\n\nAufblasbare Reittierschuhe\nBenutzen: Im Reittierausrüstungsplatz anlegen, um während des Reitens über Wasser wandeln zu können. Jeglicher Schaden hebt den Effekt auf. Funktioniert nicht auf Schlachtfeldern oder in Arenen.\n10" }
