entries[302187] = { ["name"] = "Hochgeborenenkompendium der wirbelnden Fluten", ["text"] = "Wirken in 2.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (50), Tiefrote Tinte (45), Ultramarinblaue Tinte (25), Expulsom (2)\nStellt ein Hochgeborenenkompendium der wirbelnden Fluten her.\nBeruf:\nInschriftenkunde von Battle for Azeroth (160)\nLehrer:\nNarv\nZone:\nNazjatar\nKosten:\n90\n\nHochgeborenenkompendium der wirbelnden Fluten\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n+7 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, einem Verbündeten einen Absorptionsschild zu gewähren, der für 12 Sek. bis zu 153 Schaden absorbiert. Während der Schild besteht, ist der Primärwert des Ziels um 6 erhöht.\n50" }
entries[302188] = { ["name"] = "Hochgeborenenkompendium der Zerschlagung", ["text"] = "Wirken in 2.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (50), Tiefrote Tinte (45), Ultramarinblaue Tinte (25), Expulsom (2)\nStellt ein Hochgeborenenkompendium der Zerschlagung her.\nBeruf:\nInschriftenkunde von Battle for Azeroth (160)\nLehrer:\nNarv\nZone:\nNazjatar\nKosten:\n90\n\nHochgeborenenkompendium der Zerschlagung\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n+7 [Beweglichkeit oder Stärke] Anlegen: Eure Angriffe haben eine Chance, den Gegner mit 'Vulkanischer Druck' zu belegen, wodurch er 10 Sek. lang alle 2 Sek. 3 Feuerschaden erleidet. Wenn 'Vulkanischer Druck' 6 Stapel erreicht, fügt eine Eruption allen Gegnern in der Nähe 44 Feuerschaden zu.\n50" }
entries[302189] = { ["name"] = "Hochgeborenenkompendium der Stürme", ["text"] = "Wirken in 2.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (50), Tiefrote Tinte (45), Ultramarinblaue Tinte (25), Expulsom (2)\nStellt ein Hochgeborenenkompendium der Stürme her.\nBeruf:\nInschriftenkunde von Battle for Azeroth (160)\nLehrer:\nNarv\nZone:\nNazjatar\nKosten:\n90\n\nHochgeborenenkompendium der Stürme\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n+7 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, einen Taifun zu erschaffen, der sich in Richtung von Gegnern bewegt. Der Taifun verursacht 16 Naturschaden und gewährt Euch 15 Sek. lang 4 Tempo, bis zu maximal ( 4 * 4) Tempo.\n50" }
entries[302190] = { ["name"] = "Hochgeborenenkompendium des mystischen Bollwerks", ["text"] = "Wirken in 2.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament (50), Tiefrote Tinte (45), Ultramarinblaue Tinte (25), Expulsom (2)\nStellt ein Hochgeborenenkompendium des mystischen Bollwerks her.\nBeruf:\nInschriftenkunde von Battle for Azeroth (160)\nLehrer:\nNarv\nZone:\nNazjatar\nKosten:\n90\n\nHochgeborenenkompendium des mystischen Bollwerks\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n+7 [Beweglichkeit oder Stärke] Anlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr um 78 Gesundheit geheilt werdet und 10 Sek. lang 9 Rüstung erhaltet. Bis zu ( 9 * 4) Rüstung stapelbar.\n50" }
